{
  "question": "Which statement best describes the contribution of dark matter to the total mass-energy content of the observable universe?",
  "choices": {
    "A": "It constitutes a small fraction compared to ordinary baryonic matter.",
    "B": "It accounts for roughly a quarter of the total content, exceeding baryonic matter but less than dark energy.",
    "C": "It dominates completely, making up nearly all mass-energy.",
    "D": "It contributes about the same amount as dark energy."
  }
}
